$marker=bin2hex(random_bytes(6));$email="purchase-flow-$marker@example.test";$failures=[];
function purchaseCheck(bool $ok,string $label,array &$failures):void{echo($ok?'PASS ':'FAIL ').$label.PHP_EOL;if(!$ok)$failures[]=$label;}

