    $reference='F000001';$supplierName='Workflow Supplier';$s=$c->prepare("INSERT INTO suppliers(reference,type,name,user_id) VALUES(?,'company',?,?)");$s->bind_param('ssi',$reference,$supplierName,$userId);$s->execute();$supplierId=(int)$s->insert_id;$s->close();
