    $s=$c->prepare("INSERT INTO erp_supplier_order_items(supplier_order_id,catalog_id,product_code,description,item_type,qty,price,tva_rate,unit,line_total) VALUES(?,?,?,?,'PRODUCT',10,100,19,'pièce',1190)");$s->bind_param('iiss',$orderId,$productId,$code,$productName);$s->execute();$s->close();
    $ordered=(float)$c->query("SELECT SUM(qty) FROM erp_supplier_order_items WHERE supplier_order_id=$orderId AND catalog_id=$productId")->fetch_row()[0];purchaseCheck(abs($ordered-10)<0.0005,'sent supplier order stores expected quantity',$failures);
    $supplierDocument="SUP-$marker";$notes='Rollback-only purchase workflow fixture';$s=$c->prepare("INSERT INTO erp_supplier_receptions(supplier_id,supplier_order_id,invoice_number,invoice_date,received_date,notes,status,stock_applied,total_ht,total_vat,total_ttc,user_id) VALUES(?,?,?,?,?,?,'DRAFT',0,1000,190,1190,?)");$s->bind_param('iissssi',$supplierId,$orderId,$supplierDocument,$date,$date,$notes,$userId);$s->execute();$receptionId=(int)$s->insert_id;$s->close();
