    $confirmation=confirmSupplierReception($c,$userId,$userId,$receptionId,false,false);$confirmed=$c->query("SELECT status,stock_applied,confirmed_at,confirmed_by,confirmation_hash FROM erp_supplier_receptions WHERE id=$receptionId")->fetch_assoc();$movementCount=(int)$c->query("SELECT COUNT(*) FROM product_stock_movements WHERE user_id=$userId AND reference_type='SUPPLIER_BILL' AND reference_id=$receptionId")->fetch_row()[0];$orderStatus=(string)$c->query("SELECT status FROM erp_supplier_orders WHERE id=$orderId")->fetch_row()[0];purchaseCheck(($confirmed['status']??'')==='REVIEWED'&&(int)($confirmed['stock_applied']??0)===1&&!empty($confirmed['confirmed_at'])&&(int)($confirmed['confirmed_by']??0)===$userId&&strlen((string)($confirmed['confirmation_hash']??''))===64,'atomic confirmation stores immutable metadata',$failures);purchaseCheck($movementCount===1&&$orderStatus==='RECEIVED','atomic confirmation posts stock and closes the source order',$failures);purchaseCheck(($confirmation['already_confirmed']??true)===false,'first reception confirmation is not a replay',$failures);$replay=confirmSupplierReception($c,$userId,$userId,$receptionId,false,false);$movementCountAfterReplay=(int)$c->query("SELECT COUNT(*) FROM product_stock_movements WHERE user_id=$userId AND reference_type='SUPPLIER_BILL' AND reference_id=$receptionId")->fetch_row()[0];purchaseCheck(($replay['already_confirmed']??false)===true&&$movementCountAfterReplay===1,'repeated reception confirmation is idempotent',$failures);
