    purchaseCheck(abs($received-$ordered)<0.0005,'reviewed reception matches ordered quantity',$failures);purchaseCheck($received+1>$ordered+0.0005,'additional reception would be rejected as excess',$failures);
    $boundedOrder=getSupplierOrderForUser($c,$userId,$orderId);$boundedReceptions=supplierReceptionsForUser($c,$userId,0,$orderId);purchaseCheck((int)($boundedOrder['id']??0)===$orderId&&count($boundedOrder['items']??[])===1,'single supplier order lookup returns only the requested order',$failures);purchaseCheck(count($boundedReceptions)===1&&(int)$boundedReceptions[0]['id']===$receptionId,'supplier-order reception lookup returns only linked receptions',$failures);
    $invoiceNumber="FS-$marker";$s=$c->prepare("INSERT INTO erp_supplier_invoices(user_id,supplier_id,supplier_order_id,invoice_number,invoice_date,due_date,status,currency,exchange_rate,exchange_rate_date,total_ht,total_ht_tnd,total_vat,total_tax_tnd,stamp_duty,stamp_duty_tnd,total_ttc,total_ttc_tnd,notes,created_by,validated_at) VALUES(?,?,?,?,?,?,'VALIDATED','TND',1,?,1000,1000,190,190,1,1,1191,1191,?,?,NOW())");$s->bind_param('iiisssssi',$userId,$supplierId,$orderId,$invoiceNumber,$date,$due,$date,$notes,$userId);$s->execute();$invoiceId=(int)$s->insert_id;$s->close();
    $s=$c->prepare("INSERT INTO erp_supplier_invoice_items(supplier_invoice_id,supplier_reception_item_id,product_id,description,quantity,unit_price,vat_rate,total_ht,total_ht_tnd,total_vat,deductible_vat_tnd,non_deductible_vat_tnd,total_tax_tnd,total_ttc,total_ttc_tnd) VALUES(?,?,?,?,10,100,19,1000,1000,190,190,0,190,1190,1190)");$s->bind_param('iiis',$invoiceId,$receptionItemId,$productId,$productName);$s->execute();$s->close();
    $linked=(int)$c->query("SELECT COUNT(*) FROM erp_supplier_invoice_items ii JOIN erp_supplier_reception_items ri ON ri.id=ii.supplier_reception_item_id JOIN erp_supplier_receptions r ON r.id=ri.supplier_reception_id WHERE ii.supplier_invoice_id=$invoiceId AND r.id=$receptionId AND r.user_id=$userId")->fetch_row()[0];purchaseCheck($linked===1,'supplier invoice is linked to the received item',$failures);
    $amount=500.0;$account='Cash';$s=$c->prepare("INSERT INTO erp_supplier_payments(user_id,supplier_invoice_id,amount,payment_date,method,account,recorded_by) VALUES(?,?,?,?,'CASH',?,?)");$s->bind_param('iidssi',$userId,$invoiceId,$amount,$date,$account,$userId);$s->execute();$s->close();
    $paid=(float)$c->query("SELECT SUM(amount) FROM erp_supplier_payments WHERE supplier_invoice_id=$invoiceId AND voided_at IS NULL")->fetch_row()[0];$remaining=round(1191-$paid,3);$c->query("UPDATE erp_supplier_invoices SET status='PARTIALLY_PAID' WHERE id=$invoiceId");purchaseCheck(abs($remaining-691)<0.0005,'first supplier payment creates correct partial balance',$failures);
    purchaseCheck(692>$remaining+0.0005,'supplier overpayment is rejected by remaining-balance rule',$failures);
    $amount=691.0;$s=$c->prepare("INSERT INTO erp_supplier_payments(user_id,supplier_invoice_id,amount,payment_date,method,account,recorded_by) VALUES(?,?,?,?,'CASH',?,?)");$s->bind_param('iidssi',$userId,$invoiceId,$amount,$date,$account,$userId);$s->execute();$s->close();$c->query("UPDATE erp_supplier_invoices SET status='PAID' WHERE id=$invoiceId");
    $paid=(float)$c->query("SELECT SUM(amount) FROM erp_supplier_payments WHERE supplier_invoice_id=$invoiceId AND voided_at IS NULL")->fetch_row()[0];$status=(string)$c->query("SELECT status FROM erp_supplier_invoices WHERE id=$invoiceId")->fetch_row()[0];purchaseCheck(abs($paid-1191)<0.0005&&$status==='PAID','final supplier payment closes invoice exactly',$failures);
    purchaseCheck($orderId>0&&$receptionId>0&&$invoiceId>0,'supplier order to paid invoice chain is complete',$failures);
}finally{$c->rollback();}
$s=$c->prepare('SELECT COUNT(*) FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();$remainingFixtures=(int)$s->get_result()->fetch_row()[0];$s->close();purchaseCheck($remainingFixtures===0,'purchase workflow fixtures rolled back',$failures);
